namespace MRS;
internal static class P25Tests
{
    // Independently generated by OP25 p25craft.py. See P25.md for parameters.
    internal static readonly byte[] Symbols=Convert.FromHexString("");
    internal static double[] Signal(int repeats=1,double offset=0,double gain=1,int leading=137,double noise=0,byte[]? symbols=null,double clockError=0)
    {
        var random=new Random(725);double[] levels=[600,1800,-600,-1800];
        symbols??=Symbols;
        var samples=new double[leading+(int)(symbols.Length*10*repeats/(1+clockError))+200];
        for(int n=leading;n<samples.Length-200;n++)samples[n]=levels[symbols[(int)((n-leading)*(1+clockError)/10)%symbols.Length]]*gain+offset+noise*(random.NextDouble()*2-1);
        return samples;
    }
    internal static byte[] Iq(int repeats=3,int rate=240000,byte[]? symbols=null)
    {
        double[] signal=Signal(repeats,symbols:symbols);int factor=rate/48000;byte[] iq=new byte[signal.Length*factor*2];double phase=0;
        for(int n=0;n<iq.Length/2;n++)
        {
            phase=(phase+2*Math.PI*signal[n/factor]/rate)%(2*Math.PI);
            iq[2*n]=(byte)Math.Round(127.5+85*Math.Cos(phase));iq[2*n+1]=(byte)Math.Round(127.5+85*Math.Sin(phase));
        }
        return iq;
    }
    internal static void Run(Action<bool,string> check)
    {
        check(P25Framer.EncodeNid(0x2937)==0x2937F88514ABAECC,"P25 BCH encoder agrees with independent OP25 NID vector");
        for(int bits=0;bits<=4;bits++)check(P25Framer.DecodeNid(0x2937F88514ABAECC^((1UL<<bits)-1),out int nac,out int duid,out int errors)&&nac==0x293&&duid==7&&errors==bits,$"P25 NID corrects {bits} bit errors within the conservative limit");
        check(!P25Framer.DecodeNid(0x2937F88514ABAECC^31,out _,out _,out _),"P25 NID rejects five errors beyond the preview correction limit");
        var rows=new List<P25Message>();var framer=new P25Framer();framer.Message+=rows.Add;
        foreach(byte symbol in Symbols)framer.Push(symbol);
        check(rows.Count==4 && rows[0].Nac==0x293 && rows[0].Duid==7 && !rows[0].PayloadValid,"P25 independent three-block fixture produces one verified header and three messages");
        check(rows.Skip(1).Select(m=>Convert.ToHexString(m.Raw)).SequenceEqual(new[]{"3B0001ABCDE1231001058D58","3A0001012302031001053D57","8000041002123401234572B8"}),"P25 status removal, deinterleave and trellis recover independent CRC-protected bytes");
        check(rows[1].Text.Contains("WACN ABCDE · System 123") && rows[2].Text.Contains("RFSS 2 · Site 3") && rows[3].Text.Contains("Talkgroup 4660 · Source 74565"),"P25 network, site and voice-grant fields match known fixture values");
        rows.Clear();var damaged=(byte[])Symbols.Clone();for(int n=80;n<105;n++)damaged[n]^=3;
        foreach(byte symbol in damaged.Concat(Symbols))framer.Push(symbol);
        check(rows.Count(m=>m.PayloadValid)==3 && framer.BadCrc>0,"P25 rejects corrupted control block and recovers at the next complete frame");
        rows.Clear();var status=(byte[])Symbols.Clone();for(int n=35;n<status.Length;n+=36)status[n]=3;
        foreach(byte symbol in status)framer.Push(symbol);
        check(rows.Count==4,"P25 status symbols are excluded from protected header and payload");
        check(P25Framer.DecodeBlock(Convert.FromHexString("0001010100020301020000030302010100020302000000000302010000020002020201010102000103000002000203010301010200020002020203030201020103020002030002020100010000020300010002030300030300020300000001030203"))==null,"P25 valid trellis with independently corrupted CRC is rejected");
        foreach(var fixture in new[]{(Convert.FromHexString(""),1),(Convert.FromHexString(""),2)})
        {
            rows.Clear();var shortModem=new P25C4fm();shortModem.Message+=rows.Add;
            shortModem.Process(Signal(4,symbols:fixture.Item1,clockError:.0001));
            check(rows.Count(m=>m.PayloadValid)==4*fixture.Item2,$"P25 reacquires consecutive {fixture.Item2}-block frames with 100 ppm symbol-clock offset");
        }
        foreach(var scenario in new[]{(0.0,1.0,137,0.0),(220.0,.8,19,80.0),(-180.0,-1.1,7,60.0)})
        {
            rows.Clear();var modem=new P25C4fm();modem.Message+=rows.Add;
            var signal=Signal(3,scenario.Item1,scenario.Item2,scenario.Item3,scenario.Item4);
            for(int n=0;n<signal.Length;n+=173)modem.Process(signal.AsSpan(n,Math.Min(173,signal.Length-n)));
            check(rows.Count(m=>m.PayloadValid)==9,$"P25 C4FM recovers nine messages across arbitrary blocks, DC {scenario.Item1}, gain {scenario.Item2}, noise {scenario.Item4}; actual {rows.Count(m=>m.PayloadValid)}");
        }
        rows.Clear();var noiseModem=new P25C4fm();noiseModem.Message+=rows.Add;var random=new Random(111);
        noiseModem.Process(Enumerable.Range(0,48000).Select(_=>random.NextDouble()*6000-3000).ToArray());
        check(rows.Count==0,"P25 random discriminator noise is not reported as verified data");
        foreach(int rate in new[]{240000,1920000})
        {
            rows.Clear();var iqModem=new P25C4fm();iqModem.Message+=rows.Add;
            var dsp=new ReceiveDemodulator("NFM",rate,bandwidth:12500){CaptureData=true};var iq=Iq(rate:rate);
            for(int n=0;n<iq.Length;n+=8192){dsp.Process(iq.AsSpan(n,Math.Min(8192,iq.Length-n)).ToArray());iqModem.Process(dsp.DataSamples);}
            check(rows.Count(m=>m.PayloadValid)==9,$"P25 {rate} S/s I/Q through 12.5 kHz production NFM discriminator recovers nine CRC messages; actual {rows.Count(m=>m.PayloadValid)}");
        }
        var pipeline=new P25Pipeline{Enabled=true};var context=new PacketContext("test","Synthetic P25",true,774000000,1.25);
        pipeline.Feed(Signal(),context);var observations=pipeline.Drain();
        check(observations.Length==4 && observations.All(r=>r.IsValidated&&r.Protocol=="P25 Phase I"&&r.Replay&&r.FrequencyHz==774000000),"P25 observations retain validation scope, replay attribution and frequency");
        pipeline.Clear();var partial=Signal();pipeline.Feed(partial.AsSpan(0,500),context);pipeline.Reset();pipeline.Feed(partial.AsSpan(500),context);
        check(pipeline.Counts.Messages==0,"P25 reset prevents joining frames across retunes or replay gaps");
        pipeline.Feed(Signal(70),context);int count=0;while(pipeline.Drain() is {Length:>0} batch)count+=batch.Length;
        check(count==256 && pipeline.Counts.Dropped==24,"P25 queue stays bounded and counts dropped observations");
        pipeline.Enabled=false;pipeline.Clear();pipeline.Feed(Signal(),context);check(pipeline.Drain().Length==0,"P25 disabled decoder emits no observations");
        var protectedBlock=Convert.FromHexString("C000041002123401234572B8");
        check(P25Framer.Describe(protectedBlock).Kind=="Protected TSBK","P25 protected block fields are not interpreted as cleartext");
        protectedBlock[0]=0;protectedBlock[1]=0x90;
        check(P25Framer.Describe(protectedBlock).Kind=="Manufacturer TSBK","P25 manufacturer format is retained without standard-field assumptions");
    }
}

